mapper.select:
 WHERE t.id IS NOT NULL
AND t.assignee_id = #{account}
ORDER BY t.due_at, t.id

 WHERE d.kind = 'EXPENSE' AND r.submitted_at IS NOT NULL
AND d.status = #{status}
AND r.department_id = #{departmentId}
AND r.submitted_at >= #{from}
AND r.submitted_at < DATE_ADD(#{to}, INTERVAL 1 DAY)
ORDER BY r.submitted_at DESC, d.id DESC
